case fontType1:
      if (!(fontFile = fontEngine->loadType1Font(
                           id,
                           fontsrc,
                           (const char **)((Gfx8BitFont *)gfxFont)->getEncoding()))) {
        error(errSyntaxError, -1, "Couldn't create a font for '{0:s}'",
              gfxFont->getName() ? gfxFont->getName()->getCString()
                                 : "(unnamed)");
        if (gfxFont->invalidateEmbeddedFont()) goto reload;
        goto err2;
      }
      break;
    case fontType1C:
      if (!(fontFile = fontEngine->loadType1CFont(
                           id,
                           fontsrc,
                           (const char **)((Gfx8BitFont *)gfxFont)->getEncoding()))) {
        error(errSyntaxError, -1, "Couldn't create a font for '{0:s}'",
              gfxFont->getName() ? gfxFont->getName()->getCString()
                                 : "(unnamed)");
        if (gfxFont->invalidateEmbeddedFont()) goto reload;
        goto err2;
      }
      break;
    case fontType1COT:
      if (!(fontFile = fontEngine->loadOpenTypeT1CFont(
                           id,
                           fontsrc,
                           (const char **)((Gfx8BitFont *)gfxFont)->getEncoding()))) {
        error(errSyntaxError, -1, "Couldn't create a font for '{0:s}'",
              gfxFont->getName() ? gfxFont->getName()->getCString()
                                 : "(unnamed)");
        if (gfxFont->invalidateEmbeddedFont()) goto reload;
        goto err2;
      }
      break;
    case fontTrueType:
    case fontTrueTypeOT:
        if (fileName)
         ff = FoFiTrueType::load(fileName->getCString());
        else
        ff = FoFiTrueType::make(tmpBuf, tmpBufLen);
      if (ff) {
        codeToGID = ((Gfx8BitFont *)gfxFont)->getCodeToGIDMap(ff);
        n = 256;
        delete ff;
        // if we're substituting for a non-TrueType font, we need to mark
        // all notdef codes as "do not draw" (rather than drawing TrueType
        // notdef glyphs)
        if (gfxFont->getType() != fontTrueType &&
            gfxFont->getType() != fontTrueTypeOT) {
          for (i = 0; i < 256; ++i) {
            if (codeToGID[i] == 0) {
              codeToGID[i] = -1;
            }
          }
        }
      } else {
        codeToGID = nullptr;
        n = 0;
      }
      if (!(fontFile = fontEngine->loadTrueTypeFont(
                           id,
                           fontsrc,
                           codeToGID, n))) {
        error(errSyntaxError, -1, "Couldn't create a font for '{0:s}'",
              gfxFont->getName() ? gfxFont->getName()->getCString()
                                 : "(unnamed)");
        if (gfxFont->invalidateEmbeddedFont()) goto reload;
        goto err2;
      }
